/** Original picker searches Vietnamese names by accent-insensitive prefix. */
export function normalizeCountrySearch(value: string): string {
  return value.normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/đ/g, "d").replace(/Đ/g, "D").toLowerCase();
}

export function findRoamingCountries(query: string): readonly RoamingCountry[] {
  const prefix = normalizeCountrySearch(query.trim());
  return roamingCountries.filter(country => normalizeCountrySearch(country.nameVN).startsWith(prefix));
}

/** Source router derives the destination from nameVN, not the JSON slug field. */
export function getRoamingCountrySourceUrl(country: RoamingCountry): string {
  return siteConfig.url("/goi-cuoc-roaming/") + normalizeCountrySearch(country.nameVN).replaceAll(" ", "-");
}


/** Offline flag fallback using captured flag codes; no remote assets requested. */
export function getCountryFlagEmoji(flag: string): string {
  if (/^GB-(ENG|SCT|WLS)$/.test(flag)) {
    return "\u{1F3F4}" + Array.from(flag.toLowerCase().replace("-", ""), char => String.fromCodePoint(0xE0000 + char.charCodeAt(0))).join("") + "\u{E007F}";
  }
  if (!/^[A-Z]{2}$/.test(flag)) return "🌐";
  // Unsupported source codes have no standard Unicode flag. Keep a neutral icon.
  if (["KS", "HA"].includes(flag)) return "🌐";
  return Array.from(flag, char => String.fromCodePoint(0x1F1E6 + char.charCodeAt(0) - 65)).join("");
}
